Nat.card G = Nat.card H →
  (∀ (p : ℕ), Nat.Prime p → pRank G p = pRank H p) →
    Nat.card { s // IsShiftSymmetricG s } = Nat.card { s // IsShiftSymmetricG s }

pRank G' p = pRank G p + 1 →
  (∀ (q : ℕ), Nat.Prime q → q ≠ p → pRank G' q = pRank G q) →
    Nat.card { s // IsShiftSymmetricG s } < Nat.card { s // IsShiftSymmetricG s }
